// dist/xp.js
function thresholdFor(thresholds, level) {
  return thresholds[level];
}
function levelFromXp(thresholds, totalXp) {
  let count = 0;
  for (const t2 of thresholds)
    if (t2 <= totalXp)
      count++;
  return count - 1;
}
function xpToNext(thresholds, totalXp, level) {
  const maxLevel = thresholds.length - 1;
  if (level >= maxLevel)
    return 0;
  return thresholds[level + 1] - totalXp;
}
function progressPct(thresholds, totalXp, level) {
  const maxLevel = thresholds.length - 1;
  if (level >= maxLevel)
    return 100;
  const cur = thresholds[level];
  const nxt = thresholds[level + 1];
  const pct = Math.floor((totalXp - cur) * 100 / (nxt - cur));
  if (pct < 0)
    return 0;
  if (pct > 100)
    return 100;
  return pct;
}
function xpMultiplier(usedPct) {
  if (usedPct == null)
    return 1;
  const p = Math.round(usedPct);
  if (p <= 25)
    return 2;
  if (p <= 50)
    return 1.5;
  if (p <= 75)
    return 1;
  return 0.5;
}
function typeMatchMultiplier(lineage, usedPct) {
  const p = Math.round(usedPct);
  switch (lineage) {
    case "fire":
      return p < 30 ? 1.2 : 1;
    case "water":
      return p > 70 ? 1.2 : 1;
    case "grass":
      return p >= 40 && p <= 60 ? 1.2 : 1;
    case "electric":
      return 1.2;
    case "eevee":
      return 1.1;
    default:
      return 1;
  }
}

