// dist/auth.js
var GITHUB_DEVICE_CODE_URL = "https://github.com/login/device/code";
var GITHUB_TOKEN_URL = "https://github.com/login/oauth/access_token";
async function formPost(url, params, timeoutMs) {
  try {
    const r = await fetch(url, {
      method: "POST",
      headers: { Accept: "application/json", "content-type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams(params).toString(),
      signal: AbortSignal.timeout(timeoutMs)
    });
    return await r.json();
  } catch {
    return {};
  }
}
async function jsonPost(url, body, timeoutMs, headers = {}) {
  try {
    const r = await fetch(url, {
      method: "POST",
      headers: { "content-type": "application/json", ...headers },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(timeoutMs)
    });
    return await r.json();
  } catch {
    return {};
  }
}
function coerceInterval(v) {
  const s = String(v ?? 5);
  if (!/^[0-9]+$/.test(s))
    return 5;
  const n = parseInt(s, 10);
  return n < 1 ? 5 : n;
}
async function runLogin(input, deps) {
  const { endpoint, clientId } = input;
  const { write, sleep, now } = deps;
  if (!endpoint) {
    write("  No API endpoint configured (data.json.stats_share.endpoint).\n");
    return { sessionToken: null };
  }
  const dc = await formPost(GITHUB_DEVICE_CODE_URL, { client_id: clientId, scope: "read:user" }, 1e4);
  const deviceCode = dc.device_code ?? "";
  const userCode = dc.user_code ?? "";
  const verificationUri = dc.verification_uri ?? "";
  let interval = coerceInterval(dc.interval);
  if (!deviceCode) {
    write("  GitHub device-flow request failed (is Device Flow enabled on the OAuth app?).\n");
    return { sessionToken: null };
  }
  write(`
  Open ${verificationUri}
  and enter the code:  ${userCode}

  Waiting for authorization\u2026
`);
  let accessToken = "";
  const deadline = now() + 300;
  while (now() < deadline) {
    await sleep(interval);
    const poll = await formPost(GITHUB_TOKEN_URL, { client_id: clientId, device_code: deviceCode, grant_type: "urn:ietf:params:oauth:grant-type:device_code" }, 1e4);
    accessToken = poll.access_token ?? "";
    if (accessToken)
      break;
    const err = poll.error ?? "";
    if (err === "slow_down")
      interval += 5;
    else if (err === "authorization_pending" || err === "") {
    } else {
      write(`  Login aborted (${err}).
`);
      return { sessionToken: null };
    }
  }
  if (!accessToken) {
    write("  Timed out waiting for authorization.\n");
    return { sessionToken: null };
  }
  const sess = await jsonPost(`${endpoint}/v1/auth/github/cli-session`, { access_token: accessToken }, 1e4);
  const sessionToken = sess.session_token ?? "";
  const loginName = sess.github?.login ?? "";
  if (!sessionToken) {
    write("  Session exchange with the arena failed.\n");
    return { sessionToken: null };
  }
  write(`  \u2713 Logged in as @${loginName}
`);
  return { sessionToken };
}
async function runLogout(input) {
  const { endpoint, token } = input;
  if (!token)
    return { output: "  Not logged in.\n", session: null };
  if (endpoint) {
    try {
      await fetch(`${endpoint}/v1/auth/logout`, {
        method: "POST",
        headers: { authorization: `Bearer ${token}` },
        signal: AbortSignal.timeout(5e3)
      });
    } catch {
    }
  }
  return { output: "  \u2713 Logged out.\n", session: { action: "clear" } };
}

